import glob

# Check for HTML-like patterns
files_0 = glob.glob('*.0')
files_1 = glob.glob('*.1')

def check_html(content):
    return '<html' in content.lower() or '<body' in content.lower() or '<a href' in content.lower() or '<br' in content.lower() or '&nbsp;' in content.lower()

def check_url(content):
    return 'http://' in content.lower() or 'https://' in content.lower() or 'www.' in content.lower()

def check_special(content):
    return '=' in content or '!' in content or '\$' in content or '%' in content

html_ham = 0
html_spam = 0
url_ham = 0
url_spam = 0

for f in files_0[:500]:
    with open(f, 'r', errors='replace') as fh:
        content = fh.read()
    if check_html(content):
        html_ham += 1
    if check_url(content):
        url_ham += 1

for f in files_1[:500]:
    with open(f, 'r', errors='replace') as fh:
        content = fh.read()
    if check_html(content):
        html_spam += 1
    if check_url(content):
        url_spam += 1

print(f'HTML-like in ham (sample 500): {html_ham}')
print(f'HTML-like in spam (sample 500): {html_spam}')
print(f'URL in ham (sample 500): {url_ham}')
print(f'URL in spam (sample 500): {url_spam}')
"

