import glob

# Check for special characters and patterns
files_0 = glob.glob('*.0')
files_1 = glob.glob('*.1')

def has_dollar(content):
    return '\$' in content

def has_exclamation(content):
    return '!' in content

def has_uppercase(content):
    return any(c.isupper() for c in content)

def has_digits(content):
    return any(c.isdigit() for c in content)

def has_at(content):
    return '@' in content

def has_obfuscation(content):
    return ' h @ ' in content.lower() or ' p o ' in content.lower() or ' s e x ' in content.lower()

# Sample 200 from each
sample_0 = files_0[:200]
sample_1 = files_1[:200]

for label, files in [('ham', sample_0), ('spam', sample_1)]:
    dollar = sum(1 for f in files if has_dollar(open(f, 'r', errors='replace').read()))
    exclam = sum(1 for f in files if has_exclamation(open(f, 'r', errors='replace').read()))
    upper = sum(1 for f in files if has_uppercase(open(f, 'r', errors='replace').read()))
    digits = sum(1 for f in files if has_digits(open(f, 'r', errors='replace').read()))
    at = sum(1 for f in files if has_at(open(f, 'r', errors='replace').read()))
    obfusc = sum(1 for f in files if has_obfuscation(open(f, 'r', errors='replace').read()))
    print(f'{label}: dollar={dollar}, exclam={exclam}, upper={upper}, digits={digits}, @={at}, obfusc={obfusc}')
"
